  const [merge, setMerge] = useState({ targetApplicantId: "", reason: "" });
  const [scorecard, setScorecard] = useState({ interviewId: "", roundNumber: 1, recommendation: "", status: "Draft" as RecruitmentScorecardCommand["status"], criteria: [{ name: "Technical assessment", rating: 3, notes: "" }] });
  const [talentPool, setTalentPool] = useState({ poolName: "Future hires", tags: "", notes: "", status: "Active" as RecruitmentTalentPoolCommand["status"] });
  const [onboarding, setOnboarding] = useState<RecruitmentOnboardingCase>();
  const [decision, setDecision] = useState({ decision: "Hold" as RecruitmentHiringDecisionCommand["decision"], notes: "" });
  const [privacy, setPrivacy] = useState({ action: "Grant" as RecruitmentCandidatePrivacyCommand["action"], retentionDays: 730, reason: "" });
  const [negotiation, setNegotiation] = useState({ action: "Version" as "Version" | "Counter", offerId: "", salary: "", currency: "INR", message: "" });
  const [resumeReview, setResumeReview] = useState({ decision: "Pending" as RecruitmentResumeExtractionReviewCommand["decision"], fieldsText: "skills: \
experience: \
education: \
", notes: "" });
  const stage = applicant.activityType as ApplicationStatus;
  const utilityModes: { id: Mode; label: string }[] = [{ id: "resume", label: "Resume review" }, { id: "scorecard", label: "Scorecard" }, { id: "privacy", label: "Privacy" }, { id: "negotiation", label: "Offer negotiation" }, { id: "talentpool", label: "Talent pool" }, { id: "merge", label: "Merge" }];
  const completedStep = stage === ApplicationStatus.New ? -1 : stage === ApplicationStatus.InProgress ? 0 : stage === ApplicationStatus.Shortlisted ? 1 : stage === ApplicationStatus.OnHold ? 1 : stage === ApplicationStatus.Selected ? 3 : -1;
  const activeStep = Math.max(0, primarySteps.findIndex((item) => item.id === mode));
  const canScorecard = stage === ApplicationStatus.Shortlisted || stage === ApplicationStatus.Selected;
  const canOffer = stage === ApplicationStatus.Selected;
  const canHandoff = stage === ApplicationStatus.Selected;
  const isActionEnabled = (id: Mode) => { if (id === "onboarding" && !onboarding) return false; const serverAction = workflow?.actions.find(action => action.code === (id === "handoff" ? "StartPreboarding" : id === "onboarding" ? "StartPreboarding" : id === "decision" ? "RecordHiringDecision" : id === "privacy" ? "ManageCandidatePrivacy" : id === "resume" ? "ReviewResumeExtraction" : id === "negotiation" ? "ManageOfferNegotiation" : id === "talentpool" ? "AddToTalentPool" : id === "merge" ? "MergeApplicant" : id === "interview" ? "ScheduleInterview" : id === "scorecard" ? "SubmitScorecard" : id === "screening" ? "SubmitScreening" : "CreateOffer")); return serverAction ? serverAction.enabled : id === "scorecard" ? canScorecard : id === "screening" ? stage !== ApplicationStatus.Rejected && stage !== ApplicationStatus.Selected : id === "offer" ? canOffer : id === "handoff" ? canHandoff : id === "onboarding" ? Boolean(onboarding) : id === "decision" ? [ApplicationStatus.Shortlisted, ApplicationStatus.OnHold].includes(stage) : id === "privacy" ? true : id === "resume" ? stage !== ApplicationStatus.Rejected : id === "negotiation" ? stage === ApplicationStatus.Selected : true; };
  useEffect(() => setHandoff((current) => ({ ...current, firstName: applicant.firstName ?? "", lastName: applicant.lastName ?? "", email: applicant.email ?? "" })), [applicant.firstName, applicant.lastName, applicant.email]);
  useEffect(() => { if (!open) return; void getAllDepartments(true).then(({ data }) => setDepartments((((data as any).methodResults ?? (data as any).methodResult ?? []) as unknown) as DepartmentModel[])).catch(() => setDepartments([])); void getAllEmployees({ name: "", pageNo: 1, records: 500, departmentId: [], gender: [], employmentStatus: "Active" }).then(({ data }) => setInterviewers((((data as any).methodResults ?? []) as any[]))).catch(() => setInterviewers([])); }, [open]);
  useEffect(() => { if (!open || !applicant.applicantId) return; void getRecruitmentWorkflow(applicant.applicantId).then(({ data }) => { if (data.success && data.methodResult) setWorkflow(data.methodResult); }).catch(() => setWorkflow(undefined)); void getRecruitmentOnboarding(applicant.applicantId).then(({ data }) => { if (data.success && data.methodResult) setOnboarding(data.methodResult); }).catch(() => setOnboarding(undefined)); }, [open, applicant.applicantId]);
  const changeDate = (field: "startsAtUtc" | "endsAtUtc", value: Dayjs | null) => setInterview((current) => { const next = value?.format("YYYY-MM-DDTHH:mm") ?? ""; if (field === "startsAtUtc" && next && current.endsAtUtc && new Date(current.endsAtUtc).getTime() <= new Date(next).getTime()) return { ...current, startsAtUtc: next, endsAtUtc: "" }; return { ...current, [field]: next }; });
  const saveResponse = (response: { data: { success: boolean; message?: string; errorCode?: string | null } }) => { if (!response.data.success) { const api = getApiMessage(response); throw Object.assign(new Error(api.text), { code: api.code }); } };
  const offerValidation = !offer.salary || !Number.isFinite(Number(offer.salary)) || Number(offer.salary) <= 0 ? "Enter a salary greater than zero." : !/^[A-Z]{3}$/.test(offer.currency.trim().toUpperCase()) ? "Currency must be a 3-letter code such as INR or USD." : ["Approved", "Sent"].includes(offer.status) && !offer.approvalReference.trim() ? "Approval reference is required before approving or sending an offer." : null;
